local b64 = ""

local isWin = package.config:sub(1,1) == '\\'
local isMac = not isWin and (io.popen("uname -s 2>/dev/null"):read("*l") or ""):find("Darwin") ~= nil
local sep = isWin and '\\' or '/'
local tempDir = os.getenv("TEMP") or os.getenv("TMPDIR") or (isWin and "C:\\temp" or "/tmp")
local pyScript = tempDir .. sep .. "AutoCapStyle_Core.py"

local pyWrapper = "import base64; exec(base64.b64decode('" .. b64 .. "').decode('utf-8'))"

local f = io.open(pyScript, "w")
if f then
    f:write(pyWrapper)
    f:close()
end

local function findPython()
    local localAppData = os.getenv("LOCALAPPDATA") or ""
    local programFiles = os.getenv("ProgramFiles") or "C:\\Program Files"
    
    local candidates = isWin and {
        localAppData .. "\\Programs\\Python\\Python311\\python.exe",
        localAppData .. "\\Programs\\Python\\Python312\\python.exe",
        localAppData .. "\\Programs\\Python\\Python310\\python.exe",
        "py -3.11",
        "py -3",
        "py",
        "python",
        "C:\\Python311\\python.exe",
        "C:\\Python312\\python.exe",
        "C:\\Python310\\python.exe",
        programFiles .. "\\Python311\\python.exe",
        programFiles .. "\\Python312\\python.exe",
        programFiles .. "\\Python310\\python.exe"
    } or {
        "/opt/homebrew/bin/python3",
        "/usr/local/bin/python3",
        "/usr/bin/python3",
        "/Library/Frameworks/Python.framework/Versions/3.11/bin/python3",
        "/Library/Frameworks/Python.framework/Versions/3.12/bin/python3",
        "python3",
        "python"
    }

    for _, cmd in ipairs(candidates) do
        local isValid = true
        if cmd:find("[/\\]") then
            local testHandle = io.open(cmd, "rb")
            if testHandle then
                testHandle:close()
            else
                isValid = false
            end
        end

        if isValid then
            local testCmd = isWin and ('""' .. cmd .. '" -c "import sys; print(sys.version_info[0])"" 2>&1')
                                  or ('"' .. cmd .. '" -c "import sys; print(sys.version_info[0])" 2>&1')
            local handle = io.popen(testCmd)
            if handle then
                local result = handle:read("*a")
                handle:close()
                if result and result:match("^3") then
                    return cmd
                end
            end
        end
    end
    return nil
end

local pyExec = findPython()

