        elseif isMac then
            os.execute('open ' .. dlUrl)
        else
            os.execute('xdg-open ' .. dlUrl)
        end
        disp:ExitLoop()
    end

    win:Show()
    disp:RunLoop()
    win:Hide()
else
    if isWin then
        if pyExec:find("\\") then
            os.execute('start "" "' .. pyExec .. '" "' .. pyScript .. '"')
        else
            os.execute('start "" ' .. pyExec .. ' "' .. pyScript .. '"')
        end
    else
        os.execute('"' .. pyExec .. '" "' .. pyScript .. '" &')
    end
end
